function openHero(id){modalHero=id;const h=game.roster.find(x=>x.id===id),d=byId(id),s=getStats(h),inParty=game.party.indexOf(id),lock=running()?'disabled':'';openModal(`<p class="eyebrow">HERO DOSSIER / 英雄档案</p><h2>${d.name} <small style="font:13px sans-serif;color:#99aaa9">LV.${h.level}</small></h2><p>${d.desc}</p>${running()?'<div class="hint-box">战斗中仅可查看。战后可调整专精、装备与战术。</div>':''}<div class="modal-grid"><div><div class="hero-detail-art" style="--hero:${d.color}40">${portrait(d)}</div><div class="stat-grid"><div><b>${s.hp}</b>生命值</div><div><b>${s.attack}</b>攻击力</div><div><b>${s.armor.toFixed(1)}</b>护甲</div></div><div class="form-row"><label for="hero-spec">专精</label><select id="hero-spec" ${lock}>${d.specs.map(x=>option(x,x,h.spec)).join('')}</select><label for="hero-prof">职业</label><select id="hero-prof" ${lock}>${['工匠','珠宝师','辩手'].map(x=>option(x,x,h.profession)).join('')}</select></div><p class="small-note">工匠打造护甲与武器；珠宝师打造饰品；辩手提供商店八折与开战护盾。</p><div class="progress-fill"><i style="width:${Math.min(100,h.xp/(h.level*70)*100)}%"></i></div><p class="small-note">经验 ${h.xp} / ${h.level*70} · 上阵参战即可获得经验</p><div class="modal-actions"><button class="secondary" id="train" ${lock} ${h.level>=20||game.gold<35+h.level*15?'disabled':''}>${h.level>=20?'已达等级上限':`训练升级 · ${35+h.level*15} 金币${game.gold<35+h.level*15?'（不足）':''}`}</button>${inParty>=0?`<button class="secondary" id="move-left" ${lock} ${inParty===0?'disabled':''}>← 站位前移</button><button class="secondary" id="move-right" ${lock} ${inParty===4?'disabled':''}>站位后移 →</button>`:''}</div><h3>装备 · ${Object.keys(h.equipment).length} / 7</h3><div class="equip-grid">${SLOTS.map(slot=>`<div class="equip-item">${SLOT_NAMES[slot]}<b style="color:${h.equipment[slot]?.color||'#71898c'}">${h.equipment[slot]?.name||'空置'}</b></div>`).join('')}</div><button class="secondary" id="hero-equip" style="margin-top:12px" ${lock}>从背包装备 ↗</button></div><div><h3>战术规则 <span style="font-size:10px;color:#8fa29f">条件 → 动作 → 目标</span></h3><p>同类动作按列表顺序匹配。没有匹配规则时普攻前排；大招规则未满足时会保留大招。</p><div id="rules">${h.rules.map((r,i)=>`<div class="rule" data-rule="${i}"><input type="checkbox" aria-label="启用规则 ${i+1}" class="rule-enabled" ${r.enabled!==false?'checked':''} ${lock}><select class="rule-condition" aria-label="规则条件" ${lock}>${[['always','始终'],['low_hp','自身生命 < 45%'],['enemy_cast','有敌人法力 ≥ 80%']].map(([v,l])=>option(v,l,r.condition)).join('')}</select><select class="rule-action-select" aria-label="规则动作" ${lock}>${[['focus','普攻集火'],['ultimate','施放大招'],['protect','保护 / 治疗']].map(([v,l])=>option(v,l,r.action)).join('')}</select><button class="rule-remove" aria-label="删除规则 ${i+1}" ${lock}>×</button><select class="rule-action rule-target" aria-label="规则目标" ${lock}>${targetOptions(r.target,r.action)}</select></div>`).join('')}</div><div class="modal-actions"><button class="secondary" id="add-rule" ${lock} ${h.rules.length>=8?'disabled':''}>+ 添加规则</button><button class="secondary" id="focus-back" ${lock}>预设：切后排</button><button class="secondary" id="protect-front" ${lock}>预设：保护前排</button></div><div class="hint-box">推荐：让神谕者保护前排坦克，让输出观察敌方读条；前排守卫可能保护后排。专精与装备会改变真实战斗计算。</div><p class="small-note">原型规则最多 8 条。前两位为前排，其余为后排。自动变阵、宝石镶嵌、完整俱乐部联网将在后续版本扩展。</p></div></div>`);modalHero=id;
$('#hero-spec').onchange=e=>{h.spec=e.target.value;save();renderUI();openHero(id)};$('#hero-prof').onchange=e=>{h.profession=e.target.value;save();renderUI();openHero(id)};$('#train').onclick=()=>{if(act(trainHero(game,id)))openHero(id)};$('#move-left')?.addEventListener('click',()=>swapPosition(inParty,inParty-1,id));$('#move-right')?.addEventListener('click',()=>swapPosition(inParty,inParty+1,id));$('#hero-equip').onclick=()=>openForge('inventory',id);$$('#rules .rule').forEach(row=>{const i=Number(row.dataset.rule);row.querySelector('.rule-enabled').onchange=e=>{h.rules[i].enabled=e.target.checked;save()};row.querySelector('.rule-condition').onchange=e=>{h.rules[i].condition=e.target.value;save()};row.querySelector('.rule-action-select').onchange=e=>{h.rules[i].action=e.target.value;h.rules[i].target=e.target.value==='protect'?'lowest_ally':'front';save();openHero(id)};row.querySelector('.rule-target').onchange=e=>{h.rules[i].target=e.target.value;save()};row.querySelector('.rule-remove').onclick=()=>{h.rules.splice(i,1);save();openHero(id)}});$('#add-rule').onclick=()=>{h.rules.push({condition:'always',action:'focus',target:'front',enabled:true});save();openHero(id)};$('#focus-back').onclick=()=>{h.rules=[{condition:'always',action:'focus',target:'back',enabled:true},{condition:'always',action:'ultimate',target:'back',enabled:true}];save();openHero(id);toast('已配置切后排战术')};$('#protect-front').onclick=()=>{h.rules=[{condition:'always',action:'protect',target:game.party[0],enabled:true}];save();openHero(id);toast('已配置保护首位英雄')};}
function swapPosition(a,b,id){if(running()||b<0||b>4)return;[game.party[a],game.party[b]]=[game.party[b],game.party[a]];save();renderUI();openHero(id);toast('站位已调整')}
function openGrowth(){openModal(`<p class="eyebrow">英雄成长</p><h2>你的远征同伴</h2><p>选择英雄，配置专精、职业、装备与战术。</p><div class="roster-grid">${game.roster.map(h=>heroCard(h,game.party.indexOf(h.id))).join('')}</div>`);$$('#modal [data-hero]').forEach(el=>el.onclick=()=>openHero(el.dataset.hero));}let partyDraft=[];function openRoster(){if(running()){toast('请等战斗结束后调整阵容');return}partyDraft=[...game.party];drawRoster()}
function drawRoster(){openModal(`<p class="eyebrow">THE COMPANY / 组建远征队</p><h2>每个英雄，都有自己的答案。</h2><p>选择恰好 5 名英雄。先取消一名，再选择替补；前两名会站在前排。</p><div class="hint-box">已选 ${partyDraft.length} / 5：${partyDraft.map(id=>byId(id).name).join(' → ')||'请选择英雄'}</div><div class="roster-grid">${game.roster.map((h,i)=>heroCard(h,partyDraft.indexOf(h.id),partyDraft.includes(h.id)?'chosen':'')).join('')}</div><div class="modal-actions"><button class="primary" id="confirm-party" ${partyDraft.length!==5?'disabled':''}>确认阵容 →</button><button class="secondary" id="balanced-party">推荐均衡阵容</button></div>`);$$('.roster-grid [data-hero]').forEach(el=>el.onclick=()=>{const id=el.dataset.hero;if(partyDraft.includes(id))partyDraft=partyDraft.filter(x=>x!==id);else if(partyDraft.length<5)partyDraft.push(id);else{toast('队伍已满，请先取消一名英雄');return}drawRoster()});$('#confirm-party').onclick=()=>{if(partyDraft.length!==5)return;game.party=[...partyDraft];save();renderUI();closeModal();toast('远征队整装待发')};$('#balanced-party').onclick=()=>{partyDraft=['centaur','juggernaut','shadowfiend','lina','oracle'];drawRoster()}}
function statText(stats){return Object.entries(stats).map(([k,v])=>`${{hp:'生命',attack:'攻击',armor:'护甲',haste:'攻速'}[k]||k} +${k==='haste'?Math.round(v*100)+'%':v}`).join(' · ')}
function itemCard(item,body){return `<div class="item-card" style="border-color:${item.color}77"><h4 style="color:${item.color}">${escape(item.name)}</h4><p>${item.rarity} · ${SLOT_NAMES[item.slot]} · 装备等级 ${item.level}</p><p>${statText(item.stats)}</p>${body}</div>`}
function openForge(tab='inventory',heroId=forgeHeroId||game.party[0]){forgeHeroId=heroId;forgeTab=tab;const lock=running()?'disabled':'';openModal(`<p class="eyebrow">THE FORGE / 工坊与补给</p><h2>为下一场胜利，做些准备。</h2><p>金币 <b style="color:var(--gold)">${game.gold}</b> · 余烬 <b style="color:var(--gold)">${game.essence}</b> · 装备可在英雄之间反复换装，替换后旧装备返回背包。</p>${running()?'<div class="hint-box">战斗期间仅可查看，战后再进行装备与交易。</div>':''}<div class="tab-row"><button data-forge="inventory" class="${tab==='inventory'?'active':''}">背包 · ${game.inventory.length}</button><button data-forge="craft" class="${tab==='craft'?'active':''}">打造装备</button><button data-forge="shop" class="${tab==='shop'?'active':''}">旅行商人</button></div><div id="forge-body"></div>`);$$('[data-forge]').forEach(el=>el.onclick=()=>openForge(el.dataset.forge,forgeHeroId));if(tab==='inventory'){$('#forge-body').innerHTML=`<div class="form-row"><label for="equip-hero">装备给</label><select id="equip-hero" ${lock}>${game.roster.map(h=>option(h.id,`${byId(h.id).name} · Lv.${h.level}`,heroId)).join('')}</select><span class="small-note">同部位自动替换</span></div><h3>当前穿戴</h3><div class="equip-grid">${SLOTS.map(slot=>{const item=game.roster.find(h=>h.id===heroId).equipment[slot];return `<div class="equip-item">${SLOT_NAMES[slot]}<b>${item?escape(item.name):'空置'}</b>${item?`<button data-unequip="${slot}" ${lock}>卸下至背包</button>`:''}</div>`}).join('')}</div><h3>背包装备</h3><div class="inventory">${game.inventory.map(item=>itemCard(item,`<button data-equip="${item.id}" ${lock}>装备给此英雄 ↗</button>`)).join('')||'<p>背包暂时为空。赢得战斗、打造或购买装备。</p>'}</div>`;$('#equip-hero').onchange=e=>{forgeHeroId=e.target.value;openForge('inventory',forgeHeroId);};$$('[data-unequip]').forEach(el=>el.onclick=()=>{if(running())return;if(act(unequipItem(game,forgeHeroId,el.dataset.unequip)))openForge('inventory',forgeHeroId)});$$('[data-equip]').forEach(el=>el.onclick=()=>{const id=$('#equip-hero').value;if(act(equipItem(game,id,el.dataset.equip)))openForge('inventory',id)})}else if(tab==='craft'){$('#forge-body').innerHTML=`<div class="hint-box">上阵工匠可打造护甲与武器，上阵珠宝师可打造饰品。打造保底稀有，30% 史诗、8% 传说。神器仅在远征里程碑出现。</div><div class="inventory">${SLOTS.map(slot=>`<div class="item-card"><h4>${SLOT_NAMES[slot]}</h4><p>${slot.startsWith('trinket')?'珠宝师':'工匠'}专属</p><p>需要 ${slot.startsWith('trinket')?5:6} 余烬</p><button data-craft="${slot}" ${lock} ${game.essence<(slot.startsWith('trinket')?5:6)||!game.party.some(id=>game.roster.find(h=>h.id===id).profession===(slot.startsWith('trinket')?'珠宝师':'工匠'))?'disabled':''}>开始打造</button></div>`).join('')}</div>`;$$('[data-craft]').forEach(el=>el.onclick=()=>{if(act(craftItem(game,el.dataset.craft)))openForge('inventory',heroId)})}else{$('#forge-body').innerHTML=`<div class="hint-box">${game.party.some(id=>game.roster.find(h=>h.id===id).profession==='辩手')?'辩手交涉生效：全部商品享受八折。':'上阵辩手可获得八折价格，并给全队开战增益。'}每层更新货品，可重复购买。</div><div class="inventory">${generateShop(game).map((item,i)=>itemCard(item,`<button data-buy="${i}" ${lock} ${game.gold<shopPrice(game,item)?'disabled':''}>购买 · ${shopPrice(game,item)} 金币</button>`)).join('')}</div>`;$$('[data-buy]').forEach(el=>el.onclick=()=>{if(act(buyItem(game,generateShop(game)[Number(el.dataset.buy)])))openForge('shop',heroId)})}}
function openClub(){openModal(`<p class="eyebrow">THE LEAGUE / 俱乐部概念预览</p><h2>远征之外，还有更大的舞台。</h2><div class="hint-box">本 demo 重点实现 PVE 战斗与成长。这里是 <b>AI 对手的单日杯赛演示</b>，不是真人联网比赛，不发放正式联赛奖励。</div><p>让当前五人小队参加三轮淘汰赛。结果由相同战斗引擎即时模拟；不消耗资源，也不会更改爬塔进度。</p><div class="bracket" id="bracket"><div><h3>八强赛</h3><div class="match">你的远征队<br>vs 灰羽俱乐部</div></div><div><h3>半决赛</h3><div class="match">等待八强赛结果</div></div><div><h3>冠军赛</h3><div class="match">等待半决赛结果</div></div></div><button class="primary" id="run-cup">模拟单日杯赛 →</button><p class="small-note">瑞士轮、双败赛、联赛、声望与选秀权属于完整设计，未在此原型中实现。</p>`);$('#run-cup').onclick=()=>{const g=deserialize(serialize(game));g.pendingRelics=null;g.completed=false;let won=true;const results=[];for(let i=0;i<3;i++){if(!won){results.push({skipped:true});continue}g.floor=Math.max(1,Math.min(15,game.floor-1+i*2));g.rng=20261031+i*99;const b=startBattle(g);for(let t=0;t<1500&&b.status==='running';t++)tickBattle(b,.1);won=b.status==='won';results.push({won,time:b.time,floor:g.floor})}$('#bracket').innerHTML=results.map((r,i)=>`<div><h3>${['八强赛','半决赛','冠军赛'][i]}</h3><div class="match">${r.skipped?'未晋级':`你的远征队<br>vs ${['灰羽俱乐部','星火战团','永夜学院'][i]}<br><b class="${r.won?'winner':''}">${r.won?'胜利':'落败'} · ${r.time.toFixed(1)} 秒</b>`}</div></div>`).join('');$('#run-cup').textContent=won?'冠军！再模拟一次 ↻':'调整阵容后再来 ↻'}}
function showHelp(){openModal(`<p class="eyebrow">FIELD GUIDE / 远征手册</p><h2>先赢一场，再创造你的流派。</h2><div class="hint-box">1. 点击「开始战斗」，五人小队会自动战斗。<br>2. 首次教学读条自动暂停，之后每战首次读条降至1×。每战 3 点指挥权，共享于断法、护佑与突击；选择目标后施放，暂停时也能下令。<br>3. 胜利获得经验、金币、余烬与装备。点击英雄升级、切换专精和配置战术。<br>4. 每次胜利三选一遗物形成构筑。精英路线更危险但收益更高，可随时在战前切回常规。每三层挑战首领，完成第十五层赢得远征。</div><h3>把策略变成优势</h3><p>前两位是前排，其余为后排。神谕者适合保护坦克，先看敌人机制：守卫可能保护后排，断法也可阻止治疗。每位英雄都支持「条件 → 动作 → 目标」规则，大招也可以保留至条件满足。点击英雄卡片开始调整。</p><h3>成长与失败</h3><p>失败无资源惩罚，可以免费重试；调整阵容、花金币训练、打造或购入装备均能突破难关。装备不会自动穿戴，请在工坊选择英雄后装备。重开远征需要确认，会清除当前进度。</p><h3>原型边界</h3><p>所有英雄与属性均为玩法验证数值，不是 Dota 2 正式服数据。11 位英雄含专精改造；联网 PVP、自动变阵、宝石系统与正式联赛暂未实现。俱乐部杯赛为 AI 模拟。进度仅保存在当前浏览器。</p><p class="small-note">3D 战场：拖动旋转、滚轮缩放、点击重置镜头；可随时切换 2D 战术视图与省电画质。快捷键：空格暂停 / 继续战斗，Esc 关闭面板。战斗在切换浏览器标签页后会自动暂停。</p>`)}
$('#tactics-open').onclick=()=>openHero(game.party[0]);$('#help').onclick=showHelp;$('#edit-party').onclick=openRoster;$$('[data-view]').forEach(el=>el.onclick=()=>{if(el.dataset.view==='battle'){closeModal();return}$$('[data-view]').forEach(x=>x.classList.toggle('active',x===el));if(el.dataset.view==='roster')openRoster();if(el.dataset.view==='growth')openGrowth();if(el.dataset.view==='forge')openForge();if(el.dataset.view==='club')openClub()});
$('#reset').onclick=()=>{if(running()){toast('请先完成当前战斗');return}openModal(`<p class="eyebrow">NEW EXPEDITION</p><h2>开启一段新的远征？</h2><p>这会清除当前浏览器中的英雄成长、装备和爬塔进度，无法撤销。</p><div class="modal-actions"><button id="confirm-reset" class="primary">确认重新开始</button><button id="cancel-reset" class="secondary">保留当前进度</button></div>`);$('#cancel-reset').onclick=closeModal;$('#confirm-reset').onclick=()=>{game=createGame(Date.now()%4294967296);battle=null;fx=[];paused=false;speed=1;selected=null;lastSeen=0;firstThreat=false;encounter='normal';forgeHeroId=null;$('#clock').textContent='00:00';$('#speed').textContent='1×';$('#battle-log').innerHTML='';$('#battle-log').classList.add('hidden');$('#battle-hint').textContent='点击英雄配置成长与战术';save();renderUI();$('#battle-overlay').classList.add('hidden');closeModal();toast('新的远征，新的可能。')}};
$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('#speed').textContent=`${speed}×`};function togglePause(){if(!running())return;paused=!paused;renderUI()}$('#pause').onclick=togglePause;$('#log-toggle').onclick=()=>{const hidden=$('#battle-log').classList.toggle('hidden');$('#log-toggle').setAttribute('aria-expanded',String(!hidden));$('#more-menu').open=false;};document.addEventListener('visibilitychange',()=>{if(document.hidden&&running()){paused=true;renderUI()}});
$('#start').onclick=()=>{if(running())return;if(game.pendingRelics){openRelicDraft();return}battle=startBattle(game,encounter);if(!battle)return;paused=false;firstThreat=false;lastSeen=0;fx=[];selected=null;save();$('#battle-overlay').classList.add('hidden');$('#battle-hint').textContent=encounterInfo(battle.floor,encounter).name+' · '+encounterInfo(battle.floor,encounter).desc;renderUI()};
$('#start-top').onclick=()=>$('#start').click();
function finishBattle(){const reward=settleBattle(game,battle);if(!reward.ok)return;save();renderUI();const won=battle.status==='won';const best=Object.entries(battle.damage).filter(([uid])=>uid.startsWith('a-')).sort((a,b)=>b[1]-a[1])[0];const mvp=best?battle.units.find(u=>u.uid===best[0]):null;$('#battle-overlay').innerHTML=`<div class="reward-icon">${won?'✧':'◇'}</div><p class="eyebrow">${won?'VICTORY / 胜利':'REGROUP / 重整旗鼓'}</p><h2>${reward.completed&&won?'长夜已尽，余烬不灭。':won?'又一层，被你征服。':'下一次，换一种策略。'}</h2><p>${won?battle.replay?'演练结束，无资源消耗、不发放奖励。':`${battle.replay?'演练不发放奖励 · ':''}金币 +${reward.gold}　余烬 +${reward.essence}　经验 +${reward.xp}<br><span style="color:${reward.item?.color}">${reward.item?.name||''}</span>${reward.bonusItem?` · ${reward.bonusItem.name}`:''} 已进入背包`:'本次挑战不扣除资源。<br>精英可改走常规。用护佑接下重击，或断法阻止关键施法。'}</p>${mvp?`<p style="font-size:10px">本场输出之星 · ${mvp.name} · ${Math.round(best[1])} 伤害</p>`:''}<button id="inspect-loot" class="secondary">${won?(game.pendingRelics?'选择战利遗物 ✧':'整备装备 ↗'):'调整战术 ↗'}</button>`;$('#battle-overlay').classList.remove('hidden');$('#inspect-loot').onclick=()=>won?(game.pendingRelics?openRelicDraft():openForge()):openHero(game.party[0]);$('#battle-hint').textContent=won?game.pendingRelics?'奖励已入库；选择一件遗物塑造流派，再继续向上。':'演练结束，成长与进度均保留。':'失败无惩罚。调整阵容与成长后可再次挑战。'}
function previewUnits(){return [...game.party.map((id,i)=>{const h=game.roster.find(x=>x.id===id),d=byId(id),s=getStats(h);return {...d,...h,...s,uid:`a-${id}`,team:'ally',position:i,maxHp:s.hp,mana:25,maxMana:100,shield:0}}),...enemiesForFloor(Math.min(15,game.floor),encounter)]}
function coords(u){const front=u.position<2;const x=u.team==='ally'?(front?.35:.15):(front?.65:.85);const ys=front?[.35,.68]:[.20,.49,.78];return {x:x*W,y:ys[front?u.position:u.position-2]*H}}
function rgba(hex,a){if(!hex||hex[0]!=='#')return `rgba(140,190,170,${a})`;return `rgba(${parseInt(hex.slice(1,3),16)},${parseInt(hex.slice(3,5),16)},${parseInt(hex.slice(5,7),16)},${a})`}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;DPR=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}new ResizeObserver(resize).observe(canvas);
function drawArena(t){const units=battle&&battle.status==='running'?battle.units:previewUnits();hitboxes=fallbackRenderer.render({units,events:fx,time:t,width:W,height:H,selected,paused});}
function selectUnit(u){if(running()&&u.team==='ally'){if(u.hp>0){$('#ward-target').value=u.uid;toast(`护佑目标：${u.name}。点击「护佑」施放。`)}return}if(u.team==='ally'){openHero(u.id);return}if(u.hp<=0||battle&&battle.status!=='running')return;selected=u.uid;if(running()){$('#rally-target').value=u.uid;toast(`突击目标：${u.name}。点击「突击」下令，不会更改战术。`)}else toast(`${u.name} · 敌方 ${u.position+1} 号位`);}
canvas.addEventListener('pointerdown',e=>{const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;const hit=hitboxes.find(h=>Math.hypot(h.x-x,h.y-y)<h.r);if(hit)selectUnit(hit.u)});
function frame(t){const dt=Math.min(.05,(t-lastFrame)/1000||0);lastFrame=t;frameEvents=[];if(!paused)visualTime+=dt*1000;if(running()&&!paused){tickBattle(battle,dt*speed);if(!firstThreat&&battle.units.some(u=>u.team==='enemy'&&u.hp>0&&u.casting)){firstThreat=true;speed=1;$('#speed').textContent='1×';if(!game.commanderTutorialSeen){paused=true;game.commanderTutorialSeen=true;save();toast('危险读条！首次教学已暂停。选择指令后点击「继续」，以后仅降至1×。')}renderUI()}const events=battle.events.filter(e=>e.id>lastSeen);frameEvents=events;events.forEach(e=>{fx.push({...e,created:visualTime,offset:(e.id%3-1)*11});lastSeen=e.id});if(events.length){$('#battle-log').innerHTML=battle.events.slice(-40).reverse().map(e=>`<div><b>${e.time.toFixed(1)}s</b> ${escape(e.text)} ${e.amount>0?e.amount:''}</div>`).join('')}$('#clock').textContent=`${String(Math.floor(battle.time/60)).padStart(2,'0')}:${String(Math.floor(battle.time%60)).padStart(2,'0')}`;if(battle.status!=='running')finishBattle()}if(t-lastTacticalPaint>150){renderTactical();lastTacticalPaint=t}fx=fx.filter(f=>visualTime-f.created<1100);if(view3d){try{view3d.render({units:battle&&battle.status==='running'?battle.units:previewUnits(),events:frameEvents,key:running()?battle:`preview-${game.floor}-${encounter}-${game.party.join('-')}`,dt:dt*speed,selected,paused})}catch(error){console.warn('3D render failed',error);view3d.dispose();view3d=null;setView('2d');toast('已安全切换 2D 战术模式。')}}if(viewMode==='2d'||!view3d)drawArena(visualTime);requestAnimationFrame(frame)}
renderUI();resize();requestAnimationFrame(frame);window.emberbound={version:'0.4.0',get game(){return game},get battle(){return battle},get renderer(){return view3d},get viewMode(){return viewMode}};
